class r{constructor(){this._lines=[]}get currentLine(){return this._lines[this.lineIndex]}get canRead(){return this.lineIndex<this._lines.length-1}set lines(h){this._lines.length=0;for(const e of h){if(!e||e==="\r")continue;if(e[0]==="#"){this._lines.push(e);continue}const i=e.trim();if(!i)continue;if(i.startsWith("//")){this._lines.push(e);continue}const l=i.indexOf(";");if(l===-1)this._lines.push(i);else if(l===i.length-1)i.length>1&&this._lines.push(i);else{const s=e.split(";");for(let t=0;t<s.length;t++){let n=s[t];n&&(n=n.trim(),n&&this._lines.push(n+(t!==s.length-1?";":"")))}}}}}export{r as ShaderCodeCursor};
